#!/usr/bin/env python3
"""Check the finite movsd decoder contract independently of runtime helpers."""
import argparse,hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];ap=argparse.ArgumentParser();a=ap.parse_args();D=R/'generated/tools'/'SRW-tribes';U=D/'udis86-1.7.2';out=R/'generated/sse'/'vmovsd-decoder';out.mkdir(exist_ok=True);source=R/'tests/vmovsd_decoder_test.c';sources=[source]+sorted((U/'libudis86').glob('*.c'));exe=out/'native';cmd=['clang','-O2','-Wall','-Wextra','-Werror','-DHAVE_STRING_H=1','-I',str(U)]+list(map(str,sources))+['-o',str(exe)];subprocess.run(cmd,check=True);run=subprocess.run([str(exe)],capture_output=True,text=True);assert not run.returncode and run.stdout.startswith('PASS:') and not run.stderr,(run.stdout,run.stderr)
paths=sources+sorted((U/'libudis86').glob('*.h'))+[U/'udis86.h',pathlib.Path(__file__).resolve()];report={'pass':True,'sources_sha256':{str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},'preview':False,'binary_sha256':hashlib.sha256(exe.read_bytes()).hexdigest(),'output':run.stdout.strip(),'scope':'Host decoder lengths/operand roles/reset/truncation and finite unsupported forms, not native execution.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(run.stdout.strip())
